import{f as t,o,c as a,a2 as d}from"./chunks/framework.BtbFyp-E.js";const m=JSON.parse('{"title":"GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/26-mensajes-y-documentos-impresos.md","filePath":"entregables-analisis-diseno/26-mensajes-y-documentos-impresos.md","lastUpdated":null}'),r={name:"entregables-analisis-diseno/26-mensajes-y-documentos-impresos.md"};function n(s,e,i,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="goodapps-cooperativas" tabindex="-1">GoodApps Cooperativas <a class="header-anchor" href="#goodapps-cooperativas" aria-label="Permalink to &quot;GoodApps Cooperativas&quot;">​</a></h1><h2 id="catalogo-de-mensajes-textos-y-plantillas-y-diseno-de-reportes-y-documentos-impresos" tabindex="-1">Catálogo de mensajes, textos y plantillas, y diseño de reportes y documentos impresos <a class="header-anchor" href="#catalogo-de-mensajes-textos-y-plantillas-y-diseno-de-reportes-y-documentos-impresos" aria-label="Permalink to &quot;Catálogo de mensajes, textos y plantillas, y diseño de reportes y documentos impresos&quot;">​</a></h2><p><strong>Entregable de Análisis y Diseño Detallado — Artefactos 4.6 (Catálogo de mensajes, textos y plantillas) y 4.7 (Diseño de reportes y documentos impresos)</strong></p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Producto</td><td>GoodApps Cooperativas: plataforma de gestión en la nube (SaaS multi-tenant) que reemplaza a ProCoop en cooperativas de servicios públicos y sociales</td></tr><tr><td>Documento</td><td>Portada, convenciones de tono y redacción, conteos y observaciones del catálogo de mensajes, plantillas, documentos impresos y reportes</td></tr><tr><td>Artefactos</td><td>4.6 Catálogo de mensajes, textos y plantillas · 4.7 Diseño de reportes y documentos impresos (índice <code>00-INDICE.md</code>, sección 4)</td></tr><tr><td>Partes</td><td><code>26-mensajes-y-documentos-impresos.md</code> (esta portada) · <a href="./26a-catalogo-mensajes-y-plantillas"><code>26a-catalogo-mensajes-y-plantillas.md</code></a> · <a href="./26b-documentos-impresos-y-reportes"><code>26b-documentos-impresos-y-reportes.md</code></a></td></tr><tr><td>Cooperativa piloto</td><td><strong>Laguna Larga</strong> (<code>LAG</code>), DEC-088 y DEC-089: electricidad (con prepago) y gas natural por redes; Internet es el primer servicio construido de punta a punta con datos sintéticos (DEC-005)</td></tr><tr><td>Destinatarios</td><td>Responsables de área de la cooperativa piloto, equipo de producto, diseño UX, redacción, desarrollo y QA</td></tr><tr><td>Carácter</td><td>Documento <strong>derivado</strong> de la especificación vigente; no la reemplaza. Ante cualquier diferencia prevalecen la especificación maestra (<code>00</code>), sus anexos y el registro de decisiones (<code>01</code>)</td></tr><tr><td>Versión</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr><tr><td>Fuentes principales</td><td>T03 (diccionario, reglas UX, errores <code>err.*</code>), T08 (errores RFC 9457, límites y rate limit), T09 (motor de comunicaciones, plantillas, variables, consentimiento, catálogo §9.6), T10 (catálogo de reportes §15, tableros §15.7), T11 (catálogo de eventos §12.3, motor de documentos §5.12, plantillas semilla §18.4, códigos de error §17.5, DEC-080), M05 (factura, NC, ND, talones, código de barras, distribución), M06 (QR fiscal, transparencia fiscal, CVP, libros IVA, retenciones), M07 (recibo, cupón, resumen de cuenta), M08 (avisos, intimación, corte), M15 (reportes contables), M16 (recibo de sueldo), T04 (entidades jurídicas, DEC-064), registro de decisiones (DEC-064, DEC-077, DEC-078, DEC-080, DEC-087, DEC-088, DEC-089)</td></tr></tbody></table><h3 id="control-de-versiones" tabindex="-1">Control de versiones <a class="header-anchor" href="#control-de-versiones" aria-label="Permalink to &quot;Control de versiones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Descripción del cambio</th><th>Autor</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td>Versión inicial: convenciones de tono, catálogo de mensajes de sistema, catálogo de plantillas por canal y evento, maquetas de documentos impresos, catálogo de reportes y observaciones sobre las fuentes</td><td></td></tr></tbody></table><h3 id="aprobaciones" tabindex="-1">Aprobaciones <a class="header-anchor" href="#aprobaciones" aria-label="Permalink to &quot;Aprobaciones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rol</th><th>Nombre</th><th>Firma</th><th>Fecha</th></tr></thead><tbody><tr><td>Elaboró</td><td></td><td></td><td></td></tr><tr><td>Revisó (producto / UX)</td><td></td><td></td><td></td></tr><tr><td>Revisó (cooperativa piloto LAG)</td><td></td><td></td><td></td></tr><tr><td>Aprobó</td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="indice-general" tabindex="-1">Índice general <a class="header-anchor" href="#indice-general" aria-label="Permalink to &quot;Índice general&quot;">​</a></h2><p>Esta portada:</p><ul><li>Propósito, alcance y cómo leer el catálogo</li><li><ol><li>Convenciones de tono y redacción</li></ol></li><li>Conteos del catálogo</li><li><ol start="6"><li>Observaciones e inconsistencias detectadas</li></ol></li><li><ol start="7"><li>Fuentes consultadas</li></ol></li></ul><p>Parte A — <a href="./26a-catalogo-mensajes-y-plantillas"><code>26a-catalogo-mensajes-y-plantillas.md</code></a> (artefacto 4.6):</p><ul><li><ol start="2"><li>Catálogo de mensajes de sistema (errores, validaciones, confirmaciones y avisos de proceso; errores de API RFC 9457 por módulo)</li></ol></li><li><ol start="3"><li>Catálogo de plantillas de comunicación por canal y evento disparador (canales, finalidades, variables, plantillas de WhatsApp heredadas, catálogo por evento, textos de ejemplo, mensajes impresos en factura)</li></ol></li></ul><p>Parte B — <a href="./26b-documentos-impresos-y-reportes"><code>26b-documentos-impresos-y-reportes.md</code></a> (artefacto 4.7):</p><ul><li><ol start="4"><li>Documentos impresos (convenciones de maqueta, encabezado por entidad jurídica, inventario de plantillas, 19 maquetas con zonas y campos con su origen)</li></ol></li><li><ol start="5"><li>Catálogo de reportes (contrato semántico, tableros por rol y catálogo con filtros, columnas y destinatario)</li></ol></li></ul><hr><h2 id="proposito-alcance-y-como-leer-el-catalogo" tabindex="-1">Propósito, alcance y cómo leer el catálogo <a class="header-anchor" href="#proposito-alcance-y-como-leer-el-catalogo" aria-label="Permalink to &quot;Propósito, alcance y cómo leer el catálogo&quot;">​</a></h2><h3 id="proposito" tabindex="-1">Propósito <a class="header-anchor" href="#proposito" aria-label="Permalink to &quot;Propósito&quot;">​</a></h3><p>Reunir en un solo lugar <strong>todo lo que el sistema le dice a una persona</strong>: los mensajes que aparecen en pantalla (errores, validaciones, confirmaciones y avisos), las comunicaciones que salen por correo, SMS, WhatsApp, push y bandeja de avisos, los documentos que se imprimen o se descargan en PDF y los reportes que consumen las áreas. El objetivo es que redacción, UX, desarrollo y la cooperativa piloto validen textos, estructura y origen de cada dato antes de construir cada ola.</p><h3 id="alcance" tabindex="-1">Alcance <a class="header-anchor" href="#alcance" aria-label="Permalink to &quot;Alcance&quot;">​</a></h3><ul><li><strong>Incluido:</strong> los mensajes y plantillas que la especificación ya define (T03 §10.7, T09 §9.6), los códigos de error de API declarados en los anexos, las 46 plantillas semilla de documentos de T11 §18.4 (inventario completo y maqueta de las que usa el piloto) y los reportes del catálogo consolidado de T10 §15.4 que necesita la cooperativa piloto entre O1 y O9.</li><li><strong>Recorte por piloto:</strong> se priorizan los servicios de LAG (electricidad con prepago y gas por redes) y el servicio Internet de DEC-005. El resto del catálogo de T09 y T10 se adopta tal como está en los anexos; aquí se referencia por cantidad.</li><li><strong>Excluido:</strong> diseño visual final (colores, tipografías e iconografía salen del design system de T03 §7.A y de la marca de cada cooperativa), textos legales que la especificación no fija y contenido de comunidad (muro, encuestas, boletines), que es contenido editorial y no texto de sistema.</li></ul><h3 id="como-leer-el-catalogo" tabindex="-1">Cómo leer el catálogo <a class="header-anchor" href="#como-leer-el-catalogo" aria-label="Permalink to &quot;Cómo leer el catálogo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Marca</th><th>Significado</th></tr></thead><tbody><tr><td><strong>Definido</strong></td><td>El texto, el código o el campo existe tal cual en la especificación; la columna &quot;Fuente&quot; indica dónde</td></tr><tr><td><strong>Propuesto</strong></td><td>Texto redactado por este entregable para completar un código o un caso que la especificación declara sin texto. Debe incorporarse al diccionario (T03) o a la plantilla (T09/T11) y validarse con la cooperativa piloto antes de la ola que lo usa</td></tr><tr><td><code>†</code> junto a una variable</td><td>Variable de plantilla que no figura en la lista de RF-COM-134 y se propone registrar en <code>templateVariables</code> (T09 §7.7)</td></tr><tr><td><code>[VERIFICAR]</code></td><td>Dato que depende de un relevamiento de LAG o de una validación legal todavía abierta</td></tr><tr><td><code>[TEXTO LEGAL PENDIENTE: …]</code></td><td>Zona de un documento cuyo texto exige una definición legal que la especificación no tiene; no se completa para no inventar requisitos (ver sección 6)</td></tr></tbody></table><h3 id="datos-de-ejemplo" tabindex="-1">Datos de ejemplo <a class="header-anchor" href="#datos-de-ejemplo" aria-label="Permalink to &quot;Datos de ejemplo&quot;">​</a></h3><p><strong>Todos los datos de los ejemplos son ficticios.</strong> No se usan personas, CUIT, domicilios ni números reales. De la base relevada de LAG solo se toma configuración (DEC-088), nunca datos personales. Juego de datos usado en las tres partes:</p><table tabindex="0"><thead><tr><th>Elemento</th><th>Valor ficticio</th></tr></thead><tbody><tr><td>Tenant</td><td>Cooperativa Demo Villa Ficticia (<code>TEN-001</code>, código corto de marca &quot;Coop Demo&quot;)</td></tr><tr><td>Entidad jurídica LE-01</td><td>Cooperativa Demo Villa Ficticia Ltda. — CUIT 30-00000001-0 (ficticio) — IVA Responsable Inscripto — servicios de electricidad y gas</td></tr><tr><td>Entidad jurídica LE-02</td><td>Demo Conectividad Villa Ficticia S.A. — CUIT 30-00000002-0 (ficticio) — servicio Internet</td></tr><tr><td>Domicilio legal</td><td>Av. Siempre Viva 100, Villa Ficticia, Córdoba (ficticio)</td></tr><tr><td>Titular</td><td>Ana Ejemplo — DNI 20.000.001 (ficticio) — consumidora final</td></tr><tr><td>Cuenta / suministro</td><td>Cuenta 000012345 · suministro eléctrico 100045 · medidor M-900001</td></tr><tr><td>Contactos</td><td><code>ana.ejemplo@ejemplo.test</code> · +54 9 351 000-0001</td></tr><tr><td>Empleada</td><td>Laura Demo — legajo 0042 — CUIL 27-00000003-0 (ficticio)</td></tr><tr><td>Importes</td><td>En pesos argentinos (ARS), con dos decimales y coma decimal (<code>ARS 25.095,00</code>)</td></tr></tbody></table><hr><h2 id="_1-convenciones-de-tono-y-redaccion" tabindex="-1">1. Convenciones de tono y redacción <a class="header-anchor" href="#_1-convenciones-de-tono-y-redaccion" aria-label="Permalink to &quot;1. Convenciones de tono y redacción&quot;">​</a></h2><p>Estas convenciones aplican a toda superficie: admin, PWA del socio, PWA de empleado y de campo, landing, correo, SMS, WhatsApp, push, bandeja de avisos y documentos PDF. Las que vienen de la especificación indican su fuente; las marcadas &quot;Convención de este entregable&quot; son una propuesta de estilo derivada de los textos base de T03 §10.7 y deben validarse.</p><h3 id="_1-1-voz-y-tratamiento" tabindex="-1">1.1 Voz y tratamiento <a class="header-anchor" href="#_1-1-voz-y-tratamiento" aria-label="Permalink to &quot;1.1 Voz y tratamiento&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Convención</th><th>Ejemplo correcto</th><th>Evitar</th><th>Fuente</th></tr></thead><tbody><tr><td>C-01</td><td>Español rioplatense con <strong>voseo</strong> y tuteo de cercanía (&quot;Ingresá&quot;, &quot;Revisá&quot;, &quot;Tenés&quot;); idioma único <code>es-AR</code></td><td>&quot;Revisá el último número del CUIT&quot;</td><td>&quot;Revise&quot;, &quot;Usted debe&quot;</td><td>T03 §10.7.4 y RF-UXD-168</td></tr><tr><td>C-02</td><td>La cooperativa habla en <strong>primera persona del plural</strong> cuando actúa o falla (&quot;bloqueamos&quot;, &quot;te enviamos&quot;, &quot;no pudimos&quot;)</td><td>&quot;No pudimos cargar la información&quot;</td><td>&quot;El sistema ha fallado&quot;</td><td>T03 <code>ui.error.carga</code>, <code>err.login.bloqueado</code></td></tr><tr><td>C-03</td><td>El mensaje <strong>no culpa</strong> a la persona: describe qué pasó y qué puede hacer</td><td>&quot;Los importes no coinciden con la deuda actual. Actualizá y volvé a intentar&quot;</td><td>&quot;Ingresó un importe incorrecto&quot;</td><td>T03 <code>err.pago.importesNoCoinciden</code>; RF-UXD-127</td></tr><tr><td>C-04</td><td>Registro claro y concreto, sin jerga técnica, sin siglas internas ni nombres de colecciones; los códigos técnicos se muestran solo como referencia para soporte</td><td>&quot;Algo salió mal. Probá de nuevo en unos minutos. Código: 8F2A-11C0&quot;</td><td>&quot;Error 500 en <code>cob.receipts</code>&quot;</td><td>T03 <code>err.generico</code>; RNF-NFR-091</td></tr><tr><td>C-05</td><td>Sin signos de exclamación en errores ni en avisos de deuda o corte; tono neutro y respetuoso en mora</td><td>&quot;Tenés ARS 25.095,00 vencido. Pagá ahora para evitar la suspensión&quot;</td><td>&quot;¡Atención! ¡Debe pagar ya!&quot;</td><td>Convención de este entregable (derivada de <code>por.banner.deudaVencida</code>)</td></tr><tr><td>C-06</td><td>Los textos de la interfaz son contenido, no instrucciones: nunca alteran permisos ni reglas, aunque un tenant escriba algo engañoso</td><td>—</td><td>—</td><td>RF-UXD-163</td></tr></tbody></table><h3 id="_1-2-estructura-de-cada-tipo-de-mensaje" tabindex="-1">1.2 Estructura de cada tipo de mensaje <a class="header-anchor" href="#_1-2-estructura-de-cada-tipo-de-mensaje" aria-label="Permalink to &quot;1.2 Estructura de cada tipo de mensaje&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Tipo</th><th>Estructura</th><th>Ejemplo</th><th>Fuente</th></tr></thead><tbody><tr><td>C-07</td><td>Error de validación</td><td><strong>Qué corregir</strong> + <strong>cómo</strong> (formato esperado o rango). Inline junto al campo y resumen arriba del formulario con enlaces; el formulario conserva lo cargado. Nunca <code>alert()</code> del navegador</td><td>&quot;Ingresá el DNI sin puntos (7 u 8 números)&quot;</td><td>RF-UXD-102, RF-UXD-127; T03 <code>err.formato.dni</code></td></tr><tr><td>C-08</td><td>Error de operación</td><td><strong>Qué pasó</strong> + <strong>qué hacer</strong> + <strong>código de seguimiento</strong> (<code>requestId</code>) si es inesperado</td><td>&quot;Otra persona modificó este registro. Revisá los cambios&quot;</td><td>T03 <code>err.conflicto</code>; RNF-NFR-091</td></tr><tr><td>C-09</td><td>Confirmación previa</td><td>Pregunta con el <strong>efecto concreto</strong> (cuántos, qué cambia, si es reversible); botón con el verbo de la acción (&quot;Emitir 98 facturas&quot;), nunca &quot;Aceptar&quot;; acciones irreversibles piden escribir el identificador</td><td>&quot;Para confirmar, escribí LOT-2026-00012&quot;</td><td>RF-UXD-108; T03 <code>ui.confirmar.escribir</code></td></tr><tr><td>C-10</td><td>Resultado de acción</td><td>Estado final real y, en masivas, resultado por ítem</td><td>&quot;48 aprobadas, 2 con error&quot;</td><td>RF-UXD-108</td></tr><tr><td>C-11</td><td>Estado de integración</td><td>Se distingue <strong>Pendiente</strong>, <strong>Confirmado</strong>, <strong>Falló</strong> y <strong>Resultado incierto</strong>; nunca se muestra &quot;enviado&quot; o &quot;pagado&quot; si solo está en cola o en proceso</td><td>&quot;Estamos verificando tu pago&quot;</td><td>RF-UXD-110, RF-COM-141; T03 <code>estado.pago.incierto</code></td></tr><tr><td>C-12</td><td>Estado vacío</td><td>Título comercial + acción primaria; nunca solo &quot;Sin datos&quot;</td><td>&quot;Todavía no iniciaste gestiones&quot;</td><td>RF-UXD-106</td></tr><tr><td>C-13</td><td>Proceso largo</td><td>Se informa que sigue en segundo plano y que se avisará al terminar</td><td>&quot;Procesando… podés seguir trabajando; te avisamos al terminar&quot;</td><td>RF-UXD-109; T03 <code>ui.job.enCurso</code></td></tr><tr><td>C-14</td><td>Seguridad (login y recupero)</td><td>Mensajes <strong>genéricos</strong> que no revelan si un usuario o una cuenta existe</td><td>&quot;Si los datos son correctos, te enviamos un email con los pasos&quot;</td><td>RF-UXD-117; T03 <code>login.recupero.enviado</code>; PA-UXD-14</td></tr></tbody></table><h3 id="_1-3-formatos-de-datos" tabindex="-1">1.3 Formatos de datos <a class="header-anchor" href="#_1-3-formatos-de-datos" aria-label="Permalink to &quot;1.3 Formatos de datos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Dato</th><th>Formato</th><th>Fuente</th></tr></thead><tbody><tr><td>C-15</td><td>Fecha</td><td><code>dd-mm-yyyy</code> en la zona horaria del tenant, desde el helper <code>formatDate</code>; fecha y hora <code>dd-mm-yyyy HH:mm</code></td><td>RF-UXD-101; RF-COM-134</td></tr><tr><td>C-16</td><td>Importe</td><td><code>ARS</code> + separador de miles con punto + coma decimal + 2 decimales (<code>ARS 18.450,00</code>); en documentos, número en letras cuando el documento lo exige (<code>numberToWords</code>)</td><td>RF-COM-134 (<code>money:ARS:2</code>); RF-WFL-171</td></tr><tr><td>C-17</td><td>Plural y género</td><td>Formato ICU (<code>{count, plural, one {# factura vencida} other {# facturas vencidas&amp;#125;&amp;#125;</code>) y concordancia por género del término (`{g:objeto</td><td>Nuevo</td></tr><tr><td>C-18</td><td>Identificadores</td><td>DNI y CUIT se piden sin puntos ni guiones; se muestran con el formato del documento cuando corresponde</td><td>T03 <code>login.usuario.hint</code>, <code>err.formato.dni</code></td></tr><tr><td>C-19</td><td>Datos sensibles</td><td>Contactos y CBU enmascarados en vistas y comunicaciones (<code>****0001</code>); variables marcadas <code>sensitive</code> nunca viajan en SMS, WhatsApp ni push, solo un enlace autenticado</td><td>T09 §7.7 <code>templateVariables.sensitive</code>; T09 §9.6 regla (d)</td></tr></tbody></table><h3 id="_1-4-terminologia-y-diccionario" tabindex="-1">1.4 Terminología y diccionario <a class="header-anchor" href="#_1-4-terminologia-y-diccionario" aria-label="Permalink to &quot;1.4 Terminología y diccionario&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Convención</th><th>Fuente</th></tr></thead><tbody><tr><td>C-20</td><td>Ningún texto visible es literal en el código: toda etiqueta, mensaje y ayuda es una clave del diccionario; el CI falla si aparece un literal</td><td>RF-UXD-141, RF-UXD-142</td></tr><tr><td>C-21</td><td>Los términos de negocio se referencian (<code>{t:per.asociado.one}</code>), de modo que si la cooperativa dice &quot;Asociado&quot; en lugar de &quot;Socio&quot; el cambio llega a todas las frases</td><td>RF-UXD-146, RF-UXD-150</td></tr><tr><td>C-22</td><td>Textos <strong>protegidos</strong> no editables por el tenant: leyendas fiscales y normativas, denominaciones ARCA de comprobantes, textos de consentimiento</td><td>RF-UXD-156</td></tr><tr><td>C-23</td><td>Pares de conceptos <strong>no equivalentes</strong> nunca comparten texto (por ejemplo &quot;Suspendido&quot; y &quot;Dado de baja&quot;)</td><td>RF-UXD-164; T03 <code>estado.servicio.suspendido</code></td></tr><tr><td>C-24</td><td>Las comunicaciones se renderizan con el diccionario del tenant del <strong>destinatario</strong> y conservan el texto renderizado; los documentos congelan la versión del diccionario usada al emitirse</td><td>RF-UXD-161, RF-UXD-170, RF-COM-153; PA-UXD-07 (se asume opción A)</td></tr><tr><td>C-25</td><td>Los nombres de servicios, planes y conceptos son datos del catálogo (M02), no claves de diccionario</td><td>RF-UXD-166</td></tr></tbody></table><h3 id="_1-5-convenciones-por-canal" tabindex="-1">1.5 Convenciones por canal <a class="header-anchor" href="#_1-5-convenciones-por-canal" aria-label="Permalink to &quot;1.5 Convenciones por canal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Canal</th><th>Convención</th><th>Fuente</th></tr></thead><tbody><tr><td>C-26</td><td>Correo</td><td>Asunto ≤ 60 caracteres con el hecho principal (&quot;Tu factura de noviembre ya está disponible&quot;); preencabezado con el dato clave (importe y vencimiento); un único botón de acción; pie con razón social de la entidad emisora; link de baja de un clic solo en finalidades <code>community</code> y <code>marketing</code></td><td>Asunto y preencabezado: convención de este entregable; link de baja: RF-COM-173</td></tr><tr><td>C-27</td><td>SMS</td><td>Remitente = razón social corta (≤ 11 caracteres alfanuméricos); el editor cuenta caracteres y segmentos (GSM-7 160/153, UCS-2 70/67) y bloquea si supera el máximo. <strong>Recomendación:</strong> como las vocales con tilde <code>á</code>, <code>í</code>, <code>ó</code>, <code>ú</code> fuerzan UCS-2, los SMS de más de 70 caracteres se redactan sin esas tildes para no duplicar el costo</td><td>Conteo y remitente: RF-COM-135, T09 <code>senderIdentities</code>; recomendación de tildes: convención de este entregable</td></tr><tr><td>C-28</td><td>WhatsApp</td><td>Solo plantillas aprobadas por el proveedor, con variables posicionales mapeadas a variables tipadas; el mensaje libre existe solo dentro de la sesión de 24 h iniciada desde atención (M09)</td><td>RF-COM-136</td></tr><tr><td>C-29</td><td>Push</td><td>Título ≤ 40 caracteres y cuerpo ≤ 120, con enlace profundo a la pantalla del hecho</td><td>Longitudes: convención de este entregable; enlace: RF-COM-137</td></tr><tr><td>C-30</td><td>Bandeja in-app</td><td>Título, cuerpo, enlace interno y vigencia (30 días por defecto; no vence mientras la acción siga abierta)</td><td>RF-COM-138, RF-COM-203</td></tr><tr><td>C-31</td><td>Impreso en factura</td><td>Mensajes por área con tope de caracteres: encabezado 120, cuerpo 400, pie 200, dorso 1.500</td><td>PRM-COM-047</td></tr></tbody></table><h3 id="_1-6-convenciones-de-documentos-impresos-y-pdf" tabindex="-1">1.6 Convenciones de documentos impresos y PDF <a class="header-anchor" href="#_1-6-convenciones-de-documentos-impresos-y-pdf" aria-label="Permalink to &quot;1.6 Convenciones de documentos impresos y PDF&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Convención</th><th>Fuente</th></tr></thead><tbody><tr><td>C-32</td><td>Un documento emitido se genera una vez, se guarda con hash SHA-256 y se sirve siempre igual; reimprimir crea una reimpresión marcada, nunca lo reemplaza</td><td>RF-WFL-176, RF-FAC-137</td></tr><tr><td>C-33</td><td>Marcas de agua estándar: <strong>BORRADOR</strong>, <strong>ANULADO</strong>, <strong>COPIA</strong>, <strong>SIMULACIÓN</strong>; reimpresión con la leyenda <strong>DUPLICADO</strong></td><td>RF-WFL-177, RF-FAC-138, RF-MED-119</td></tr><tr><td>C-34</td><td>Formatos A4, Carta, Oficio y ticket de 80 mm; PDF/A-2b para documentos de archivo (fiscales y legales)</td><td>RF-WFL-175 (DEC-080)</td></tr><tr><td>C-35</td><td>Encabezado con la <strong>entidad jurídica emisora</strong> del documento (DEC-064), no con la del tenant genérico</td><td>RF-CFG-134, RF-CFG-137; M05 <code>invoices.legalEntityId</code></td></tr><tr><td>C-36</td><td>El bloque fiscal (CAE, QR, leyendas de ARCA) no es editable por el tenant; el tenant personaliza pie y textos en zonas editables</td><td>T11 §18.4; RF-WFL-179</td></tr><tr><td>C-37</td><td>Las plantillas de documentos fiscales y legales se publican con aprobación</td><td>RF-WFL-174</td></tr><tr><td>C-38</td><td>Tipografía de documentos: lista cerrada de tres tipografías autoalojadas con licencia libre (se asume la opción recomendada de PA-UXD-17)</td><td>PA-UXD-17</td></tr><tr><td>C-39</td><td>Los documentos verificables llevan código y QR de verificación pública que muestra tipo, fecha, emisor y hash, sin datos personales</td><td>RF-WFL-201, RF-COB-089</td></tr></tbody></table><h3 id="_1-7-accesibilidad-de-los-textos" tabindex="-1">1.7 Accesibilidad de los textos <a class="header-anchor" href="#_1-7-accesibilidad-de-los-textos" aria-label="Permalink to &quot;1.7 Accesibilidad de los textos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Convención</th><th>Fuente</th></tr></thead><tbody><tr><td>C-40</td><td>Los mensajes de error se asocian al campo (<code>aria-describedby</code>) y los toasts, progresos y estados offline se anuncian por regiones <code>aria-live</code></td><td>RF-UXD-126, RF-UXD-134</td></tr><tr><td>C-41</td><td>Los textos respetan límites de largo por clave (un botón con límite 24 rechaza un texto de 60) y no rompen la maqueta</td><td>RF-UXD-136</td></tr><tr><td>C-42</td><td>Imágenes de marca con texto alternativo del diccionario (&quot;Logo de {marca}&quot;); ilustraciones decorativas con <code>alt=&quot;&quot;</code></td><td>RF-UXD-138</td></tr><tr><td>C-43</td><td>El campo de código OTP acepta pegado y autocompletado; nunca se exige transcribir sin permitir pegar</td><td>RF-UXD-130</td></tr></tbody></table><hr><h2 id="conteos-del-catalogo" tabindex="-1">Conteos del catálogo <a class="header-anchor" href="#conteos-del-catalogo" aria-label="Permalink to &quot;Conteos del catálogo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Cantidad</th><th>Detalle</th><th>Dónde</th></tr></thead><tbody><tr><td>Convenciones de tono y redacción</td><td>43</td><td>C-01 a C-43</td><td>Sección 1 (esta portada)</td></tr><tr><td>Mensajes de sistema</td><td><strong>152</strong></td><td>MSG-001 a MSG-152: 65 de interfaz con texto definido en T03 o en el anexo dueño y 87 con texto <strong>propuesto</strong> (16 confirmaciones y avisos de pantalla y 71 errores de API declarados sin texto)</td><td>Sección 2 (parte A)</td></tr><tr><td>Errores de API RFC 9457 (incluidos en los 152)</td><td>71</td><td>6 transversales de T08, 13 de T01, 5 de T02, 17 de T11, 3 de T03, 5 de M06, 10 de M07, 3 de M08 y 9 de otros módulos (M01, M03, M10, M13, M15, M17 y T10)</td><td>Sección 2.6 (parte A)</td></tr><tr><td>Tipos de comunicación catalogados</td><td><strong>70</strong></td><td>Tipos del catálogo de T09 §9.6 que usa el piloto (O1 a O10), con evento disparador, canales y variables</td><td>Sección 3.5 (parte A)</td></tr><tr><td>Plantillas por canal (tipo × canal)</td><td><strong>225</strong></td><td>Suma de los canales admitidos por los 70 tipos</td><td>Sección 3.5 (parte A)</td></tr><tr><td>Plantillas de WhatsApp heredadas de ProCoop</td><td>6</td><td>Mapeadas a tipos de comunicación (incluidas en las 225)</td><td>Sección 3.4 (parte A)</td></tr><tr><td>Textos de ejemplo redactados</td><td>24</td><td>Plantillas completas con datos ficticios</td><td>Sección 3.6 (parte A)</td></tr><tr><td>Documentos impresos con maqueta</td><td><strong>19</strong></td><td>DOC-01 a DOC-19</td><td>Sección 4 (parte B)</td></tr><tr><td>Plantillas de documentos inventariadas</td><td>46 + 2</td><td>Las 46 semilla de T11 §18.4 y 2 documentos que la especificación pide sin plantilla semilla</td><td>Sección 4.3 (parte B)</td></tr><tr><td>Reportes catalogados con filtros, columnas y destinatario</td><td><strong>56</strong></td><td>Subconjunto del catálogo de T10 §15.4 que usa el piloto</td><td>Sección 5.3 (parte B)</td></tr><tr><td>Tableros por rol</td><td>12</td><td>Tableros de T10 §15.7 que usa el piloto</td><td>Sección 5.2 (parte B)</td></tr><tr><td>Observaciones e inconsistencias</td><td>20</td><td>OBS-01 a OBS-20</td><td>Sección 6 (esta portada)</td></tr></tbody></table><hr><h2 id="_6-observaciones-e-inconsistencias-detectadas" tabindex="-1">6. Observaciones e inconsistencias detectadas <a class="header-anchor" href="#_6-observaciones-e-inconsistencias-detectadas" aria-label="Permalink to &quot;6. Observaciones e inconsistencias detectadas&quot;">​</a></h2><p>Se registran para su tratamiento en la especificación. <strong>No se corrigió ningún anexo</strong>; este entregable trabaja con lo que está escrito y, donde falta un dato legal, deja la zona marcada como pendiente.</p><table tabindex="0"><thead><tr><th>N.º</th><th>Tema</th><th>Observación</th><th>Fuentes</th><th>Efecto en este entregable</th></tr></thead><tbody><tr><td>OBS-01</td><td>Formato de los códigos de error</td><td>Los anexos usan al menos seis formatos para el <code>type</code> de RFC 9457: barra y guiones (<code>wfl/sod-violation</code>, <code>fis/arca-rejected</code>, <code>mor/mode-not-allowed</code>, <code>per/relationship-scope</code>), punto y camelCase (<code>cob.caja.sesionCerrada</code>, <code>tec.workOrder.duplicate</code>, <code>med.meter.alreadyInstalled</code>, <code>uxd.publish.forbidden</code>), guion bajo (<code>sod_self_approval</code>, <code>version_conflict</code>), guiones sin prefijo de módulo (<code>tenant-suspended</code>, <code>client-suspended</code>), mayúsculas (<code>POS_CONFLICT</code>) y clave de diccionario (<code>dict:con.errors.periodClosed</code>). T08 RNF-NFR-091 exige RFC 9457 pero no fija el formato ni la URI base del <code>type</code>; solo T10 fija una URI estable (<code>https://developers.goodapps.coop/problems/&amp;lt;tipo&gt;</code>), y únicamente para la API externa. M10 además informa sus errores en un campo <code>code</code> en lugar de <code>type</code></td><td>T01 §11; T02; T03 §17.2; T08 RNF-NFR-091; T10; T11 §17.5; M06; M07 §11; M08; M10; M13; M15; M17</td><td>Se transcriben los códigos tal cual; la sección 2.6 agrupa por módulo</td></tr><tr><td>OBS-02</td><td>Textos de los errores de módulo</td><td>RNF-NFR-091 pide que los 4xx muestren un mensaje por clave de diccionario en español, pero T03 §10.7.4 solo define 26 errores genéricos. Ninguno de los 71 códigos de API catalogados tiene texto para el usuario</td><td>T08 RNF-NFR-091; T03 §10.7.4</td><td>Los 71 textos de la sección 2.6 son <strong>propuestos</strong></td></tr><tr><td>OBS-03</td><td>Claves de diccionario citadas sin definir</td><td><code>uxd.error.dobleControl</code> (ESC-UXD-03) y <code>con.errors.periodClosed</code> (M15 ESC-03) se usan como mensajes, pero no figuran en el catálogo base de T03 (§10.7) ni en las claves agregadas (§10.9.10)</td><td>T03 §17.2; M15 §17</td><td>Se catalogan con texto propuesto</td></tr><tr><td>OBS-04</td><td>Palabras de baja por SMS y WhatsApp</td><td>El proceso P-COM-10 lista <code>BAJA</code>, <code>STOP</code>, <code>NO</code>, <code>CANCELAR</code>; el valor por defecto de PRM-COM-064 es <code>BAJA</code>, <code>STOP</code>, <code>CANCELAR</code>, <code>SALIR</code>. Además, <code>NO</code> como palabra de baja puede capturar respuestas comunes a otras preguntas</td><td>T09 §9.11; T09 §14 PRM-COM-064</td><td>El ejemplo de confirmación de baja no fija la lista</td></tr><tr><td>OBS-05</td><td>Consumidores de eventos sin T09</td><td>En el catálogo consolidado de eventos de T11 §12.3, los consumidores de EVT-FAC-07 <code>fac.invoice.issued</code>, EVT-FIS-01 <code>fis.invoice.authorized</code>, EVT-FAC-10 <code>fac.creditNote.issued</code>, EVT-COB-04 <code>cob.payment.confirmed</code>, EVT-COB-16 <code>cob.directDebit.rejected</code>, EVT-COB-20 <code>cob.paymentIntent.statusChanged</code> y EVT-MOR-12 (<code>mor.interruption.scheduled</code>) no incluyen a T09, aunque T09 §9.6 los usa como disparadores de comunicaciones. Lo mismo ocurre con EVT-CAT-09 <code>cat.contract.activated</code>, EVT-CAT-12 <code>cat.contract.reactivated</code> y EVT-CAT-15 <code>cat.contract.terminated</code>, que T09 §9.6 cita por nombre sin su identificador EVT</td><td>T11 §12.3; T09 §9.6.3, §9.6.4, §9.6.5</td><td>Se toma T09 §9.6 como fuente del disparador</td></tr><tr><td>OBS-06</td><td>&quot;M10&quot; donde correspondería T09</td><td>Los consumidores de EVT-COB-04, EVT-COB-16 y EVT-COB-20 incluyen a M10 (técnica), y el job JOB-COB-11 de M07 dice que el resumen de cuenta se entrega &quot;por M10 a los canales del grupo&quot;. Por función, la entrega por canales es de T09 (y la reconexión tras pago sí es de M10, lo que puede explicar solo el caso de EVT-COB-04)</td><td>T11 §12.3; M07 §9 (JOB-COB-11)</td><td>DOC-08 indica la entrega por T09 y deja la observación</td></tr><tr><td>OBS-07</td><td>Dueño del talón y del cupón</td><td>M05 mapea <code>TALONFAC</code> a <code>paymentSlips</code> (talón sumado y talón por cuota) y la plantilla TPL-FAC-04 &quot;Talón y cupón de pago&quot; tiene como dueño a M05; M07 mapea también <code>TALONFAC</code> (cuota 0 = talón sumado) a <code>paymentCoupons</code> y RF-FAC-151 dice que el cupón único lo emite M07. Quedan dos dueños posibles para el talón sumado y una plantilla con dueño distinto del emisor del cupón</td><td>M05 §7.7, RF-FAC-149, RF-FAC-151; M07 §7.29, §19; T11 §18.4</td><td>DOC-04 (talón, M05) y DOC-05 (cupón, M07) se dibujan por separado</td></tr><tr><td>OBS-08</td><td>Documentos sin plantilla semilla</td><td>La especificación pide imprimir el <strong>comprobante de recarga prepaga</strong> con su token (RF-MED-119) y la <strong>constancia de comunicación</strong> en PDF con hash (RF-COM-146, JOB-COM-17), pero ninguno está entre las 46 plantillas semilla de T11 §18.4. El recarga prepaga es crítico para LAG (CTR-COB-21)</td><td>M03 RF-MED-115, RF-MED-119; T09 RF-COM-146; T11 §18.4</td><td>DOC-16 y DOC-17 se dibujan con código de plantilla &quot;sin asignar&quot;</td></tr><tr><td>OBS-09</td><td>Dos motores de render para cartas</td><td>RF-COM-152 dice que las cartas de mora y circulares se generan en PDF &quot;usando el motor de render de COM&quot;; T11 RF-WFL-170 a 175 y DEC-080 definen un único motor de documentos HTML → PDF en T11</td><td>T09 RF-COM-152; T11 §5.12; DEC-080</td><td>Se asume el motor de T11 para todo PDF</td></tr><tr><td>OBS-10</td><td>Ola de las plantillas de mora</td><td>T11 §18.4 asigna ola O5 a TPL-MOR-01 a 05 y aclara que &quot;la ola de cada plantilla es la del módulo dueño&quot;, pero el módulo de mora M08 está en O6 (sus tipos de comunicación de T09 §9.6.5 también son O6)</td><td>T11 §18.4; M08; T09 §9.6.5</td><td>Las maquetas DOC-10 a DOC-12 indican O6 con la observación</td></tr><tr><td>OBS-11</td><td>Contenido fiscal obligatorio del comprobante</td><td>M05 RF-FAC-135 remite los &quot;datos fiscales exigidos&quot; a M06, y M06 define datos del QR (RF-FIS-061), CAE y vencimiento, CVP (RF-FIS-090), transparencia fiscal (RF-FIS-062) y la sección de aporte de capital (RF-FIS-161), pero no hay un listado cerrado del contenido obligatorio de la representación impresa por letra y tipo de comprobante (leyendas, condición de venta, datos del receptor exigibles, período facturado)</td><td>M05 RF-FAC-135; M06 §5.5</td><td>El bloque fiscal de las maquetas solo lista lo especificado y deja <code>[TEXTO LEGAL PENDIENTE]</code></td></tr><tr><td>OBS-12</td><td>Contenido regulatorio de facturas de servicios públicos</td><td>Para electricidad y gas de LAG solo está prevista la tabla normativa de rubros permitidos por jurisdicción (RF-FIS-012, Ley provincial 10739, O7). No hay relevamiento de los datos que ERSeP o ENARGAS exigen imprimir en la factura (por ejemplo, datos de categoría, consumo o reclamos)</td><td>M06 RF-FIS-012; T12 parte 1 (ficha de agua); DEC-089</td><td>Los bloques por servicio de DOC-01 llevan <code>[VERIFICAR]</code></td></tr><tr><td>OBS-13</td><td>Textos legales de mora y corte</td><td>El preaviso mínimo, la constancia exigida y las ventanas de corte están &quot;A validar&quot; (PA-MOR-06, PA-MOR-10, PA-COM-05; la plantilla ERSeP de PRM-MOR-206 está <code>toValidate</code>). No hay texto legal para el aviso de deuda, la intimación ni el aviso de corte</td><td>M08 RF-MOR-088, RF-MOR-120, RN-MOR-145; T09 PA-COM-05</td><td>DOC-10 a DOC-12 dejan zonas <code>[TEXTO LEGAL PENDIENTE]</code></td></tr><tr><td>OBS-14</td><td>Precedencia de marca en documentos</td><td>La marca de un documento se resuelve por la variante de la entidad jurídica emisora (<code>legalEntities.brandingVariantKey</code> → <code>tenantBrandings.variants</code>) o, sin variante, por la marca base del tenant (T03 §7.B). Por otro lado, los logos por sucursal (<code>branchOverrides</code>, PA-UXD-10, todavía &quot;A validar&quot;) heredan &quot;sucursal → tenant&quot; (RN-UXD-016). No está definido qué logo lleva un documento emitido en una sucursal con logo propio por una entidad que tiene variante de marca</td><td>T03 RF-UXD-028, RN-UXD-016, §7.B (<code>variants</code>, <code>branchOverrides</code>), PA-UXD-10; T04 §7.14</td><td>Las maquetas usan la variante de la entidad (o la marca base) e ignoran el logo de sucursal</td></tr><tr><td>OBS-15</td><td>Texto del concepto sin descripción duplicado</td><td>El texto que se imprime cuando un concepto no tiene descripción (V2 2318) está a la vez como parámetro <code>fac.print.unknownConceptText</code> (PRM-FAC-153, M05) y como clave <code>fac.concepto.desconocido</code> (T03 §10.9.10, canales <code>admin</code> y <code>documentos</code>)</td><td>M05 §14.7; T03 §10.9.10</td><td>Se cita la clave de diccionario</td></tr><tr><td>OBS-16</td><td>Opt-out &quot;sí&quot; en tipos transaccionales</td><td>RF-COM-171 dice que la finalidad <code>transactional</code> se puede desactivar por canal pero con al menos un canal activo; sin embargo, el catálogo marca opt-out total (&quot;sí&quot;) en tipos <code>trx</code> como <code>fac.invoice.dueReminder</code>, <code>tar.promotion.ended</code>, <code>cob.creditBalance.created</code> y <code>mor.installment.due</code></td><td>T09 RF-COM-171; T09 §9.6.4, §9.6.5</td><td>La sección 3.5 transcribe el valor del catálogo</td></tr><tr><td>OBS-17</td><td>Constancia de libre deuda sin contenido</td><td>TPL-COB-03 existe y SIG-CERT-FISCAL prevé firmarla, pero ningún requisito de M07 define su alcance (por cuenta, por servicio o por entidad jurídica), su vigencia ni cómo trata los pagos en proceso</td><td>T11 §18.4, §18.5; M07 §5</td><td>DOC-09 marca esos campos como <code>[VERIFICAR]</code></td></tr><tr><td>OBS-18</td><td>Registro de variables incompleto</td><td>RF-COM-134 enumera 14 variables de ejemplo; el resto de las que necesitan los 70 tipos no está registrado por tipo de comunicación</td><td>T09 RF-COM-134, §7.7</td><td>Las variables adicionales se marcan con <code>†</code></td></tr><tr><td>OBS-19</td><td>Entidad jurídica como filtro de reportes</td><td>Los libros IVA, la contabilidad y los recibos son por entidad jurídica (RF-FIS-167, DEC-064, DEC-087), pero <code>reportDefinitions.scopeDimensions</code> de T10 solo admite sucursal, zona, servicio, cuadrilla, propio y caja</td><td>T10 §7.1; M06 RF-FIS-167</td><td>La sección 5.3 agrega el filtro &quot;entidad jurídica&quot; donde lo exige el anexo dueño</td></tr><tr><td>OBS-20</td><td>Ola de la firma del recibo de sueldo</td><td>El perfil SIG-SUE-EMPLEADOR (firma digital) indica &quot;DEC-078; O8&quot;, mientras TPL-SUE-01 y M16 están en O9; además, la admisión del recibo digital sigue marcada <code>[VERIFICAR]</code> en M16</td><td>T11 §18.4, §18.5; M16 §21; DEC-078</td><td>DOC-15 indica O9 y la observación</td></tr></tbody></table><hr><h2 id="_7-fuentes-consultadas" tabindex="-1">7. Fuentes consultadas <a class="header-anchor" href="#_7-fuentes-consultadas" aria-label="Permalink to &quot;7. Fuentes consultadas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fuente</th><th>Secciones usadas</th></tr></thead><tbody><tr><td><code>docs/especificacion/01-registro-decisiones.md</code></td><td>DEC-005, DEC-064, DEC-077, DEC-078, DEC-080, DEC-087, DEC-088, DEC-089</td></tr><tr><td>T03 UXD</td><td>§5.8 a §5.11 (reglas UX, login, accesibilidad, diccionario), §10.7 (catálogo base del diccionario: <code>ui.*</code>, <code>estado.*</code>, <code>err.*</code>, <code>login.*</code>, <code>por.*</code>), §10.9.10, §17.2, PA-UXD-07, PA-UXD-10, PA-UXD-14, PA-UXD-17</td></tr><tr><td>T08 NFR</td><td>RNF-NFR-026, RNF-NFR-075, RNF-NFR-078, RNF-NFR-091, RNF-NFR-174, RNF-NFR-210</td></tr><tr><td>T09 COM</td><td>§5.8 a §5.13, §7.7, §9.6 (catálogo transaccional), §9.7 a §9.11, §14 (PRM-COM-032, 047, 060, 062, 063, 064), §15</td></tr><tr><td>T10 BIA</td><td>§7.1, §15.1 a §15.4, §15.7, §15.8</td></tr><tr><td>T11 WFL</td><td>§5.11 a §5.14, §12.3 (catálogo de eventos), §17.5, §18.4, §18.5</td></tr><tr><td>T01 PLA, T02 IAM, T04 CFG</td><td>Códigos de error (T01 §11, T02 §9 y §17), entidades jurídicas (T04 RF-CFG-134 a 137 y §7.14, incluida <code>brandingVariantKey</code>)</td></tr><tr><td>M03 MED</td><td>RF-MED-115, RF-MED-119, RF-MED-121</td></tr><tr><td>M05 FAC</td><td>§5.16 a §5.19, §6.8, §7.3, §7.7, §7.8, §14.5 a §14.7, §15</td></tr><tr><td>M06 FIS</td><td>RF-FIS-008, RF-FIS-012, RF-FIS-061, RF-FIS-062, RF-FIS-090, RF-FIS-112 a 122, RF-FIS-161, RF-FIS-167, §9.8, §9.9</td></tr><tr><td>M07 COB</td><td>RF-COB-023, RF-COB-086 a 090, RF-COB-154, RF-COB-193, §7.8, §7.12, §7.29, §11, §15</td></tr><tr><td>M08 MOR</td><td>RF-MOR-080 a 099, RF-MOR-120, RF-MOR-221, §15 (REP-MOR), PA-MOR-06, PA-MOR-10</td></tr><tr><td>M15 CON, M16 SUE</td><td>Reportes contables (vía T10 §15.4.6); RF-SUE-104 (recibo art. 140 LCT), libro de sueldos</td></tr><tr><td>Entregables previos</td><td><code>05-wireframes-pantallas-piloto.md</code> (convención de portada y datos de demostración), <code>11-glosario-negocio.md</code> (terminología)</td></tr></tbody></table>',54)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
